import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        String s = next();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long answer = 0;
        for (int start = 0, i = 1; i <= n; i++) {
            if (i == n || s.charAt(i) != s.charAt(start)) {
                // Take the k largest profits of the run [start, i).
                Arrays.sort(a, start, i);
                for (int j = i - 1; j >= Math.max(start, i - k); j--) answer += a[j];
                start = i;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	s := token()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	answer := 0
	for start, i := 0, 1; i <= n; i++ {
		if i == n || s[i] != s[start] {
			// Take the k largest profits of the run [start, i).
			run := a[start:i]
			sort.Sort(sort.Reverse(sort.IntSlice(run)))
			for j := 0; j < len(run) && j < k; j++ {
				answer += run[j]
			}
			start = i
		}
	}
	fmt.Println(answer)
}
